  <script>
    const inputs = document.querySelectorAll('.otp-input');
    const verifyBtn = document.getElementById('verify-button');
    const timerDisplay = document.getElementById('timer');
    const countdownText = document.getElementById('countdown-text');
    const resendBtn = document.getElementById('resend-btn');

    // إدارة التبديل التلقائي بين خانات الإدخال
    inputs.forEach((input, index) => {
      input.addEventListener('input', (e) => {
        const val = e.target.value.replace(/[^0-9]/g, '');
        e.target.value = val;

        if (val) {
          input.classList.add('filled');
          if (index < inputs.length - 1) {
            inputs[index + 1].focus();
          }
        } else {
          input.classList.remove('filled');
        }
      });

      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace' && !input.value && index > 0) {
          inputs[index - 1].focus();
        }
      });

      // التعامل مع اللصق المباشر لكامل الرمز
      input.addEventListener('paste', (e) => {
        e.preventDefault();
        const pastedData = (e.clipboardData || window.clipboardData)
          .getData('text')
          .replace(/[^0-9]/g, '')
          .slice(0, 6);

        if (pastedData) {
          pastedData.split('').forEach((char, i) => {
            if (inputs[i]) {
              inputs[i].value = char;
              inputs[i].classList.add('filled');
            }
          });
          const nextIndex = Math.min(pastedData.length, inputs.length - 1);
          inputs[nextIndex].focus();
        }
      });
    });

    // عداد الوقت التنازلي (45 ثانية)
    let timeLeft = 45;
    let timerInterval = null;

    function startCountdown() {
      timeLeft = 45;
      resendBtn.style.display = 'none';
      countdownText.style.display = 'inline';

      clearInterval(timerInterval);
      timerInterval = setInterval(() => {
        timeLeft--;
        const seconds = timeLeft < 10 ? `0${timeLeft}` : timeLeft;
        timerDisplay.textContent = `0:${seconds}`;

        if (timeLeft <= 0) {
          clearInterval(timerInterval);
          countdownText.style.display = 'none';
          resendBtn.style.display = 'inline-block';
        }
      }, 1000);
    }

    resendBtn.addEventListener('click', () => {
      inputs.forEach(input => {
        input.value = '';
        input.classList.remove('filled');
      });
      inputs[0].focus();
      startCountdown();
    });

    startCountdown();
  </script>
